window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8052b859adcc955b"]={"versions": [{"id": "FIG-8052b859adcc955b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der internen Software-Komponentenarchitektur in der AUTOSAR Classic Platform (Software Component Template). Das Diagramm modelliert den komponenteninternen Datenaustausch zwischen Ausführungseinheiten (<code>RunnableEntity</code>) über <code>InterRunnableVariable</code> innerhalb eines <code>InternalBehavior</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>InternalBehavior</code> (Spezialisierung von <code>ARElement</code>): Kapselt das interne Verhalten einer Software-Komponente; besitzt das Attribut <code>supportsMultipleInstantiation: Boolean</code>. Es komponiert über <code>+runnable</code> (Kardinalität <code>1..*</code>) Instanzen von <code>RunnableEntity</code> (Gegenseite <code>+behavior</code>) sowie über <code>+interRunnableVariable</code> (Kardinalität <code>0..*</code>) Instanzen von <code>InterRunnableVariable</code>.\n</li><li><code>RunnableEntity</code> (Spezialisierung von <code>Identifiable</code>): Ausführbare Einheit mit den Attributen <code>canBeInvokedConcurrently: Boolean</code>, <code>minimumStartInterval: Float</code> und <code>symbol: String</code>. Greift lesend über die gerichtete Assoziation <code>+readVariable</code> (Kardinalität <code>*</code>) und schreibend über <code>+writtenVariable</code> (Kardinalität <code>*</code>) auf <code>InterRunnableVariable</code> zu.\n</li><li><code>InterRunnableVariable</code> (Spezialisierung von <code>DataPrototype</code>, welches von <code>Identifiable</code> erbt und mit <code>«atpPrototype»</code> stereotypt ist): Repräsentiert die geteilte Variable. Sie verfügt über das Attribut <code>communicationApproach: CommunicationApproachType</code> und referenziert optional über die gerichtete Assoziation <code>+initValue</code> (Kardinalität <code>0..1</code>) eine <code>ValueSpecification</code>.\n</li><li><code>CommunicationApproachType</code> (<code>«enumeration»</code>): Definiert die Übertragungsarten mit den Literalen <code>explicit</code> und <code>implicit</code>.\n</li><li><code>ValueSpecification</code>: Abstrakte Spezifikation des Initialwerts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Kommunikation erfolgt asynchron oder synchron gesteuert durch <code>RunnableEntity</code>-Aufrufe. Eine lesende <code>RunnableEntity</code> greift über <code>+readVariable</code>, eine schreibende über <code>+writtenVariable</code> auf dieselbe <code>InterRunnableVariable</code> zu. Der Zugriff wird gemäß <code>communicationApproach</code> entweder implizit (Kopie bei Task-Start/Ende) oder explizit (direkter API-Zugriff zur Laufzeit) abgewickelt. Vor dem ersten Schreibzugriff bestimmt die über <code>+initValue</code> referenzierte <code>ValueSpecification</code> den definierten Startzustand; fehlt diese, ist das Verhalten bei verfrühtem Lesezugriff undefiniert. Mehrfachinstanziierung des umschließenden <code>InternalBehavior</code> bedingt getrennte Variableninstanzen je Komponenteninstanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler von Software-Komponenten und BSW/RTE-Generatoren gilt:</p>\n<ul class=\"fig-list\"><li>Jede <code>InterRunnableVariable</code> muss typisiert sein (über Vererbung von <code>DataPrototype</code>).\n</li><li>Falls Lesezugriffe vor dem ersten Schreibzugriff stattfinden können, ist zwingend ein <code>+initValue</code> via <code>ValueSpecification</code> zu modellieren, um undefiniertes Verhalten der RTE zu verhindern.\n</li><li>Die Nebenläufigkeit (<code>canBeInvokedConcurrently</code>) mehrerer Runnables beim Zugriff auf dieselbe <code>InterRunnableVariable</code> erfordert adäquate Synchronisationsmechanismen (z. B. OS-Interruptsperren oder Semaphoren), insbesondere bei explizitem Zugriffsansatz (<code>communicationApproach = explicit</code>).\n</li><li>Die Mindestabstandsvorgabe <code>minimumStartInterval</code> steuert das Scheduling periodischer Runnables.\n</li></ul>"}, {"id": "FIG-43d97478f5e94b62", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der internen Software-Komponentenarchitektur in der AUTOSAR Classic Platform (Software Component Template). Das Diagramm modelliert den komponenteninternen Datenaustausch zwischen Ausführungseinheiten (<code>RunnableEntity</code>) über <code>InterRunnableVariable</code> innerhalb eines <code>InternalBehavior</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>InternalBehavior</code> (Spezialisierung von <code>ARElement</code>): Kapselt das interne Verhalten einer Software-Komponente; besitzt das Attribut <code>supportsMultipleInstantiation: Boolean</code>. Es komponiert über <code>+runnable</code> (Kardinalität <code>1..*</code>) Instanzen von <code>RunnableEntity</code> (Gegenseite <code>+behavior</code>) sowie über <code>+interRunnableVariable</code> (Kardinalität <code>0..*</code>) Instanzen von <code>InterRunnableVariable</code>.\n</li><li><code>RunnableEntity</code> (Spezialisierung von <code>ExecutableEntity</code>): Ausführbare Einheit mit den Attributen <code>canBeInvokedConcurrently: Boolean</code>, <code>minimumStartInterval: Float</code> und <code>symbol: String</code>. Greift lesend über die gerichtete Assoziation <code>+readVariable</code> (Kardinalität <code>*</code>) und schreibend über <code>+writtenVariable</code> (Kardinalität <code>*</code>) auf <code>InterRunnableVariable</code> zu.\n</li><li><code>InterRunnableVariable</code> (Spezialisierung von <code>DataPrototype</code>, welches von <code>Identifiable</code> erbt und mit <code>«atpPrototype»</code> stereotypt ist): Repräsentiert die geteilte Variable. Sie verfügt über das Attribut <code>communicationApproach: CommunicationApproachType</code> und referenziert optional über die gerichtete Assoziation <code>+initValue</code> (Kardinalität <code>0..1</code>) eine <code>ValueSpecification</code>.\n</li><li><code>CommunicationApproachType</code> (<code>«enumeration»</code>): Definiert die Übertragungsarten mit den Literalen <code>implicit</code> und <code>explicit</code>.\n</li><li><code>ValueSpecification</code>: Spezifikation des Initialwerts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Kommunikation erfolgt asynchron oder synchron gesteuert durch <code>RunnableEntity</code>-Aufrufe. Eine lesende <code>RunnableEntity</code> greift über <code>+readVariable</code>, eine schreibende über <code>+writtenVariable</code> auf dieselbe <code>InterRunnableVariable</code> zu. Der Zugriff wird gemäß <code>communicationApproach</code> entweder implizit (Kopie bei Task-Start/Ende) oder explizit (direkter API-Zugriff zur Laufzeit) abgewickelt. Vor dem ersten Schreibzugriff bestimmt die über <code>+initValue</code> referenzierte <code>ValueSpecification</code> den definierten Startzustand; fehlt diese, ist das Verhalten bei verfrühtem Lesezugriff undefiniert. Mehrfachinstanziierung des umschließenden <code>InternalBehavior</code> bedingt getrennte Variableninstanzen je Komponenteninstanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler von Software-Komponenten und BSW/RTE-Generatoren gilt:</p>\n<ul class=\"fig-list\"><li>Jede <code>InterRunnableVariable</code> muss typisiert sein (über Vererbung von <code>DataPrototype</code>).\n</li><li>Falls Lesezugriffe vor dem ersten Schreibzugriff stattfinden können, ist zwingend ein <code>+initValue</code> via <code>ValueSpecification</code> zu modellieren, um undefiniertes Verhalten der RTE zu verhindern.\n</li><li>Die Nebenläufigkeit (<code>canBeInvokedConcurrently</code>) mehrerer Runnables beim Zugriff auf dieselbe <code>InterRunnableVariable</code> erfordert adäquate Synchronisationsmechanismen (z. B. OS-Interruptsperren oder Semaphoren), insbesondere bei explizitem Zugriffsansatz (<code>communicationApproach = explicit</code>).\n</li><li>Die Mindestabstandsvorgabe <code>minimumStartInterval</code> steuert das Scheduling periodischer Runnables.\n</li></ul>"}, {"id": "FIG-13cb6354a22655cf", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der internen Software-Komponentenarchitektur in der AUTOSAR Classic Platform (Software Component Template). Das Diagramm modelliert den komponenteninternen Datenaustausch zwischen Ausführungseinheiten (<code>RunnableEntity</code>) über <code>InterRunnableVariable</code> innerhalb eines <code>InternalBehavior</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>InternalBehavior</code> (Spezialisierung von <code>ARElement</code>): Kapselt das interne Verhalten einer Software-Komponente; besitzt das Attribut <code>supportsMultipleInstantiation :Boolean</code>. Es komponiert über <code>+runnable</code> (Kardinalität <code>1..*</code>) Instanzen von <code>RunnableEntity</code> (Gegenseite <code>+behavior</code>) sowie über <code>+interRunnableVariable</code> (Kardinalität <code>0..*</code>) Instanzen von <code>InterRunnableVariable</code>.\n</li><li><code>RunnableEntity</code> (Spezialisierung von <code>ExecutableEntity</code>): Ausführbare Einheit mit den Attributen <code>canBeInvokedConcurrently :Boolean</code>, <code>minimumStartInterval :Float</code> und <code>symbol :CIdentifier</code>. Greift lesend über die gerichtete Assoziation <code>+readVariable</code> (Kardinalität <code>*</code>) und schreibend über <code>+writtenVariable</code> (Kardinalität <code>*</code>) auf <code>InterRunnableVariable</code> zu.\n</li><li><code>InterRunnableVariable</code> (Spezialisierung von <code>DataPrototype</code>, welches von <code>Identifiable</code> erbt und mit <code>«atpPrototype»</code> stereotypt ist): Repräsentiert die geteilte Variable. Sie verfügt über das Attribut <code>communicationApproach :CommunicationApproachType</code> und referenziert optional über die gerichtete Assoziation <code>+initValue</code> (Kardinalität <code>0..1</code>) eine <code>ValueSpecification</code>.\n</li><li><code>CommunicationApproachType</code> (<code>«enumeration»</code>): Definiert die Übertragungsarten mit den Literalen <code>implicit</code> und <code>explicit</code>.\n</li><li><code>ValueSpecification</code>: Spezifikation des Initialwerts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Kommunikation erfolgt asynchron oder synchron gesteuert durch <code>RunnableEntity</code>-Aufrufe. Eine lesende <code>RunnableEntity</code> greift über <code>+readVariable</code>, eine schreibende über <code>+writtenVariable</code> auf dieselbe <code>InterRunnableVariable</code> zu. Der Zugriff wird gemäß <code>communicationApproach</code> entweder implizit (Kopie bei Task-Start/Ende) oder explizit (direkter API-Zugriff zur Laufzeit) abgewickelt. Vor dem ersten Schreibzugriff bestimmt die über <code>+initValue</code> referenzierte <code>ValueSpecification</code> den definierten Startzustand; fehlt diese, ist das Verhalten bei verfrühtem Lesezugriff undefiniert. Mehrfachinstanziierung des umschließenden <code>InternalBehavior</code> bedingt getrennte Variableninstanzen je Komponenteninstanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler von Software-Komponenten und BSW/RTE-Generatoren gilt:</p>\n<ul class=\"fig-list\"><li>Jede <code>InterRunnableVariable</code> muss typisiert sein (über Vererbung von <code>DataPrototype</code>).\n</li><li>Das Attribut <code>symbol</code> muss als <code>CIdentifier</code> den Namenskonventionen der Programmiersprache C für Funktionsbezeichner genügen.\n</li><li>Falls Lesezugriffe vor dem ersten Schreibzugriff stattfinden können, ist zwingend ein <code>+initValue</code> via <code>ValueSpecification</code> zu modellieren, um undefiniertes Verhalten der RTE zu verhindern.\n</li><li>Die Nebenläufigkeit (<code>canBeInvokedConcurrently</code>) mehrerer Runnables beim Zugriff auf dieselbe <code>InterRunnableVariable</code> erfordert adäquate Synchronisationsmechanismen (z. B. OS-Interruptsperren oder Semaphoren), insbesondere bei explizitem Zugriffsansatz (<code>communicationApproach = explicit</code>).\n</li><li>Die Mindestabstandsvorgabe <code>minimumStartInterval</code> steuert das Scheduling periodischer Runnables.\n</li></ul>"}], "trans": [{"from": "FIG-8052b859adcc955b", "to": "FIG-43d97478f5e94b62", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>RunnableEntity</code>: Generalisierung von <code>Identifiable</code> geändert zu <code>ExecutableEntity</code>.\n</li><li><code>CommunicationApproachType</code>: Literale von <code>+ explicit:</code> / <code>+ implicit:</code> zu <code>implicit</code> / <code>explicit</code> formatiert.\n</li></ul>"}, {"from": "FIG-43d97478f5e94b62", "to": "FIG-13cb6354a22655cf", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>RunnableEntity</code>: Attributtyp von <code>symbol</code> von <code>String</code> zu <code>CIdentifier</code> geändert.\n</li></ul>"}]};
